(function(){const o=document.getElementById("outline-headings"),a=document.querySelector("main");if(!o||!a)return;const i=Array.from(a.querySelectorAll("h1, h2, h3, h4"));let l=0;for(const e of i){if(!e.id){const c=(e.textContent||"").toLowerCase().trim().normalize("NFD").replace(/[̀-ͯ]/g,"").replace(/[^a-z0-9]+/g,"-").replace(/(^-|-$)/g,"")||`section-${l++}`;e.id=c}const t=document.createElement("li");t.className=`outline__item outline__item--${e.tagName.toLowerCase()}`;const n=document.createElement("a");n.href=`#${e.id}`,n.textContent=e.textContent||"",t.appendChild(n),o.appendChild(t)}})();
